function PageHeader({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle: string; action?: React.ReactNode }) {
  return <div className="page-header"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p className="page-subtitle">{subtitle}</p></div>{action}</div>;
}

function StatCard({ label, value, delta, icon: Icon, down = false }: { label: string; value: string; delta: string; icon: React.ElementType; down?: boolean }) {
  return <div className="panel stat-card"><div className="stat-top"><span className="stat-label">{label}</span><span className="stat-icon"><Icon size={15} /></span></div><div className="stat-value">{value}</div><div className={`stat-delta ${down ? "down" : ""}`}>{down ? <ArrowDownRight size={13} /> : <ArrowUpRight size={13} />}{delta}</div></div>;
}

