function InventoryIntelligence() {
  const navigate = useAppNavigation(); const [filter, setFilter] = useState("All products");
  const rows = filter === "At risk" ? inventoryModels.filter((item) => item.tone === "red" || item.status === "incomplete") : filter === "Healthy" ? inventoryModels.filter((item) => item.tone === "teal") : inventoryModels;
  const atRisk = inventoryModels.filter((item) => item.tone === "red" || item.status === "incomplete").length;
  return <>
    <PageHeader eyebrow="Intelligence · Inventory" title="Inventory Intelligence" subtitle="Inventory is not a stock number. It is a forward-looking decision about demand, lead time, and cash." action={<button className="button primary" onClick={() => navigate("/cash")}><CircleDollarSign size={14} /> Check purchase capacity</button>} />
    <div className="grid grid-4" style={{ marginBottom: 15 }}><StatCard label="Tracked SKUs" value={String(inventoryModels.length)} delta="Demo inventory foundation" icon={Package} /><StatCard label="At stockout risk" value={String(atRisk)} delta="Coverage versus lead time" icon={Activity} down /><StatCard label="Healthy coverage" value="Data-aware" delta="No missing input is treated as zero" icon={Clock3} /><StatCard label="Reorder context" value="Supplier + cash" delta="Review before approval" icon={CircleDollarSign} down /></div>
    <div className="panel panel-pad"><div className="section-head"><div><h2>Stock health by product</h2><p>Forecasts use sales velocity, available stock, configured safety stock, and supplier lead time.</p></div><div className="filter-row">{["All products", "At risk", "Healthy"].map((x) => <button key={x} className={`filter-chip ${filter === x ? "active" : ""}`} onClick={() => setFilter(x)}>{x}</button>)}</div></div><div className="inventory-item" style={{ color: "#71809e", fontSize: 10, textTransform: "uppercase", letterSpacing: ".08em" }}><span>Product</span><span>Stock</span><span>Coverage</span><span>Velocity</span><span>Action</span></div>{rows.map((item) => <div className="inventory-item" key={item.sku}><div className="inventory-name"><strong>{item.name}</strong><span>{item.sku} · {item.supplierName ?? "Supplier not configured"}</span></div><div className="stock-number">{item.stock ?? "No data"}</div><div className="inventory-progress"><span><span>{item.coverage}</span><span>{item.stockout}</span></span><div className="bar-track"><div className="bar-fill" style={{ width: item.tone === "red" ? "24%" : item.tone === "teal" ? "72%" : "45%", background: item.tone === "red" ? "linear-gradient(90deg,#db6c7f,#e8b458)" : undefined }} /></div></div><div className="coverage"><strong>{item.velocity}</strong></div><div><span className={`tag ${item.tone}`}>{item.signal}</span></div><button className="button ghost" onClick={() => navigate(item.productId === "pima" ? "/decisions?item=pima" : "/products")}>{item.productId === "pima" ? "Review" : "Inspect"} <ChevronRight size={12} /></button></div>)}</div>
    <div className="grid grid-2" style={{ marginTop: 15 }}><div className="panel panel-pad"><div className="section-head"><div><h2>Decision inputs</h2><p>Each recommendation exposes its calculation inputs.</p></div><CircleHelp size={15} color="#7f8daa" /></div><div className="metric-row"><span>Pima supplier lead time</span><strong>{inventoryModels[0].leadTime}</strong></div><div className="metric-row"><span>Pima MOQ</span><strong>{inventoryModels[0].moq}</strong></div><div className="metric-row"><span>Recommended reorder</span><strong className="warn">{inventoryModels[0].reorderQuantity}</strong></div><div className="metric-row"><span>Missing-input policy</span><strong className="warn">Show incomplete · never assume zero</strong></div></div><div className="panel panel-pad"><div className="section-head"><div><h2>Decision shortcut</h2><p>Connect stock to cash before a supplier commitment.</p></div><Zap size={16} color="#9c90ff" /></div><p style={{ color: "#a5b0c9", fontSize: 12, lineHeight: 1.6, margin: "0 0 15px" }}>Pima coverage is {inventoryModels[0].coverage}; supplier lead time is {inventoryModels[0].leadTime}. Review the recommendation and its cash impact before approval.</p><button className="button primary" onClick={() => navigate("/decisions?item=pima")}>Open Pima decision <ChevronRight size={13} /></button></div></div>
  </>;
}
function CashAwareDecision() {
  const [qty, setQty] = useState(200); const [confirmed, setConfirmed] = useState(false); const scenario = demoCashAwareDecision(qty);
  const safe = scenario.cashFloorConfigured && scenario.projectedCash.minorUnits !== undefined && scenario.cashFloor.minorUnits !== undefined && scenario.projectedCash.minorUnits >= scenario.cashFloor.minorUnits;
  const purchaseHeight = Math.min(88, qty / 300 * 72); const projectedHeight = scenario.projectedCash.minorUnits === undefined || scenario.currentCash.minorUnits === undefined ? 18 : Math.max(18, scenario.projectedCash.minorUnits / scenario.currentCash.minorUnits * 100);
  return <>
    <PageHeader eyebrow="Finance · Operating cash" title="Cash-Aware Decision" subtitle="Operationally right is not always financially safe. ProfitPilot combines purchasing, true cost, expected profit, and cash before you commit." action={<button className="button ghost" onClick={() => toast("Cash rule editor opened.")}><Settings2 size={14} /> Edit cash rules</button>} />
    <div className="detail-grid"><div className="panel panel-accent panel-pad"><div className="section-head"><div><span className="tag amber">{scenario.lifecycle.replace("_", " ")}</span><h2 style={{ marginTop: 10 }}>Should you order Pima now?</h2><p>One decision, fully connected across inventory and cash.</p></div><div className="stat-icon"><CircleDollarSign size={17} /></div></div><div className="grid grid-2" style={{ margin: "20px 0 17px" }}><div className="panel soft panel-pad"><div className="stat-label">Operational recommendation</div><div className="stat-value" style={{ fontSize: 22 }}>Order {qty} units</div><div className="stat-delta"><ArrowUpRight size={13} /> Stockout estimate {scenario.stockout} · lead time {scenario.leadTime}</div></div><div className="panel soft panel-pad"><div className="stat-label">Cash rule</div><div className="stat-value" style={{ fontSize: 22 }}>{scenario.cashFloor.display}</div><div className="stat-delta down"><ArrowDownRight size={13} /> {scenario.cashFloorConfigured ? "Minimum operating cash" : "Not configured"}</div></div></div><div className="section-head"><div><h2>Adjust the quantity</h2><p>Use the slider to see the projected cash impact.</p></div><strong style={{ color: "#dce4fb" }}>{qty} units</strong></div><input aria-label="Reorder quantity" type="range" min="50" max="300" step="10" value={qty} onChange={(e) => setQty(Number(e.target.value))} style={{ width: "100%", accentColor: "#8b7cf6" }} /><div className="chart-labels"><span>50 units</span><span>300 units</span></div><div className="metric-row"><span>Supplier lead time</span><strong>{scenario.leadTime}</strong></div><div className="metric-row"><span>Order cost</span><strong className={scenario.reorderCost.unavailable ? "warn" : ""}>{scenario.reorderCost.display}</strong></div><div className="metric-row"><span>Projected cash after known obligations</span><strong className={safe ? "good" : "bad"}>{scenario.projectedCash.display}</strong></div>{scenario.missingInputs.length > 0 && <div className="metric-row"><span>Data completeness</span><strong className="warn">{scenario.missingInputs.join(" · ")}</strong></div>}<div className="panel soft panel-pad" style={{ marginTop: 16, borderColor: safe ? "rgba(68,201,170,.35)" : "rgba(232,164,68,.35)" }}><div style={{ display: "flex", alignItems: "flex-start", gap: 10 }}><Lightbulb size={16} color={safe ? "#68dfc5" : "#f1bb65"} /><div><strong style={{ fontSize: 12 }}>{safe ? "Cash constraint is clear" : scenario.cashFloorConfigured ? "Cash constraint is active" : "Cash floor is not configured"}</strong><p style={{ margin: "5px 0 0", color: "#8694b2", fontSize: 11, lineHeight: 1.5 }}>{safe ? "This quantity keeps projected cash above the configured operating floor." : scenario.cashFloorConfigured ? "This quantity would reduce projected cash below the configured minimum." : "ProfitPilot cannot assess floor compliance until a cash floor is configured."}</p></div></div></div><div style={{ display: "flex", gap: 8, marginTop: 17, flexWrap: "wrap" }}><button className="button ghost" onClick={() => setQty(150)}><RefreshCw size={13} /> Use 150-unit alternative</button><button className={`button ${confirmed ? "success" : "primary"}`} onClick={() => { setConfirmed(true); toast("Demo decision marked for review; it is not persisted or executed."); }}>{confirmed ? <><Check size={13} /> Review marked</> : <><ShoppingCart size={13} /> Save decision</>}</button></div></div>
      <div className="panel panel-pad"><div className="section-head"><div><h2>Cash bridge</h2><p>What changes when this order is added?</p></div><span className={`tag ${safe ? "teal" : "red"}`}>{safe ? "Within rule" : scenario.cashFloorConfigured ? "Below rule" : "Floor missing"}</span></div><div className="waterfall"><div className="waterfall-col"><b>{scenario.currentCash.display}</b><div className="waterfall-bar" style={{ height: "100%" }} /><label>Available<br />cash</label></div><div className="waterfall-col"><b>-{scenario.obligations.display}</b><div className="waterfall-bar minus" style={{ height: "43%" }} /><label>Known<br />obligations</label></div><div className="waterfall-col"><b>-{scenario.reorderCost.display}</b><div className="waterfall-bar minus" style={{ height: `${purchaseHeight}%` }} /><label>Planned<br />purchase</label></div><div className="waterfall-col"><b>{scenario.projectedCash.display}</b><div className={`waterfall-bar ${safe ? "" : "threshold"}`} style={{ height: `${projectedHeight}%` }} /><label>Projected<br />cash</label></div></div><div className="metric-row"><span>Saved operating floor</span><strong>{scenario.cashFloor.display}</strong></div><div className="metric-row"><span>Decision status</span><strong>{scenario.lifecycle.replace("_", " ")} · Demo only</strong></div><div className="metric-row"><span>Next best action</span><strong className="warn">{safe ? "Proceed to supplier review" : "Review quantity, cash floor, or missing inputs"}</strong></div></div>
    </div>
  </>;
}
