function OrderBreakdown({ compact = false }: { compact?: boolean }) { return <div className={compact ? "" : "panel panel-pad"}><div className="section-head"><div><h2>Order #{orderModel.id}</h2><p>{orderModel.source} · {new Intl.DateTimeFormat("en", { month: "short", day: "numeric" }).format(new Date(orderModel.orderedAt))} · {orderModel.status}</p></div><span className="tag violet">{orderModel.trueCostStatus}</span></div><div className="metric-row"><span>Revenue</span><strong>{orderModel.revenue.display}</strong></div><div className="metric-row"><span>Discounts</span><strong>{orderModel.discounts.display}</strong></div>{orderModel.items.map((item) => <div className="metric-row" key={item.title}><span>{item.title} · {item.quantity} unit</span><strong>{item.revenue.display}</strong></div>)}<div className="panel soft panel-pad" style={{ marginTop: 15 }}><div className="metric-row"><span>True Cost status</span><strong className="warn">{orderModel.trueCostStatus}</strong></div><div className="metric-row"><span>True Profit status</span><strong className="warn">{orderModel.trueProfitStatus}</strong></div><div className="metric-row"><span>Refund / return policy</span><strong>Not applicable for this paid demo order</strong></div></div></div>; }
function TrueCostEngine() { const navigate = useAppNavigation(); const [selected, setSelected] = useState(products[0]); const [orderView, setOrderView] = useState(false); return <><PageHeader eyebrow="Foundational calculation layer" title="True Cost Engine" subtitle="محرك التكلفة الحقيقية · Understand exactly where your money goes and what each sale really earns." action={<button className="button primary" onClick={() => navigate("/cost-settings")}><Settings2 size={14} /> Configure costs</button>} /><div className="grid grid-4" style={{ marginBottom: 15 }}><StatCard label="True revenue" value="125,400 SAR" delta="12.4% vs last month" icon={BarChart3} /><StatCard label="Total true costs" value="71,280 SAR" delta="Advertising up 12%" icon={Database} down /><StatCard label="True net profit" value="54,120 SAR" delta="43.2% net margin" icon={CircleDollarSign} /><StatCard label="Incomplete cost data" value="3 items" delta="Configure to improve accuracy" icon={CircleHelp} down /></div><div className="grid grid-main"><div className="panel panel-accent panel-pad"><div className="section-head"><div><h2>{orderView ? "Order #10482 · Profit breakdown" : "Product true cost breakdown"}</h2><p>{orderView ? "One order, all costs, one auditable profit number." : "Click a product to see direct and allocated cost drivers."}</p></div><div className="filter-row"><button className={`filter-chip ${!orderView ? "active" : ""}`} onClick={() => setOrderView(false)}>Product</button><button className={`filter-chip ${orderView ? "active" : ""}`} onClick={() => setOrderView(true)}>Order #10482</button></div></div>{!orderView ? <div className="table-wrap"><table><thead><tr><th>Product</th><th>Units</th><th>Revenue</th><th>True cost</th><th>Net profit</th><th>Margin</th></tr></thead><tbody>{products.map((p) => <tr key={p.code} onClick={() => setSelected(p)} style={{ cursor: "pointer" }}><td><div className="product-cell"><div className="product-thumb">IC</div><div><div className="product-name">{p.name}</div><div className="product-meta">{p.code}</div></div></div></td><td>{p.units}</td><td>{p.revenue}</td><td>{p.trueCost}</td><td><strong className="good">{p.profit}</strong></td><td><strong className={p.toneClass}>{p.margin}</strong></td></tr>)}</tbody></table></div> : <OrderBreakdown compact />}</div><div className="panel panel-pad"><div className="section-head"><div><span className="tag violet">{orderView ? "Order #10482" : "Selected product"}</span><h2 style={{ marginTop: 9 }}>{orderView ? "IRONCLAD Pima T-Shirt" : selected.name}</h2><p>{orderView ? "149 SAR selling price · Card payment" : `${selected.code} · source-aware calculation`}</p></div><CircleDollarSign size={18} color="#9c90ff" /></div><div>{costBreakdown.map((cost) => <div className="metric-row" key={cost.label}><span>{cost.label}</span><div style={{ display: "flex", gap: 8, alignItems: "center" }}><strong>{cost.value}</strong><SourceBadge source={cost.source} /></div></div>)}</div><div className="panel soft panel-pad" style={{ marginTop: 14 }}><div className="metric-row"><span>Total True Cost</span><strong className="warn">84.30 SAR</strong></div><div className="metric-row"><span>Net Profit</span><strong className="good">64.70 SAR</strong></div><div className="metric-row"><span>Net Margin</span><strong className="good">43.4%</strong></div></div><button className="button ghost" style={{ width: "100%", marginTop: 12 }} onClick={() => navigate("/cost-settings")}><Settings2 size={13} /> Manage allocation rules</button></div></div><div className="panel panel-pad" style={{ marginTop: 15 }}><div className="section-head"><div><h2>Cost information completeness</h2><p>ProfitPilot never silently assumes missing costs are zero.</p></div><span className="tag amber">3 items not configured</span></div><div className="grid grid-3"><div className="alert-row"><span className="alert-severity warning" /><div className="alert-copy"><strong>Customs / import cost</strong><span>True profit may be understated.</span></div><button onClick={() => navigate("/cost-settings")}>Add cost</button></div><div className="alert-row"><span className="alert-severity warning" /><div className="alert-copy"><strong>Other operating costs</strong><span>Manual allocation is not configured.</span></div><button onClick={() => navigate("/cost-settings")}>Add cost</button></div><div className="alert-row"><span className="alert-severity positive" /><div className="alert-copy"><strong>Payment fees</strong><span>Calculated from provider rule.</span></div><button onClick={() => toast("Payment fee rule: 2.9% + 1 SAR")}>View</button></div></div></div></>; }

function CostOverview() { const navigate = useAppNavigation(); return <><PageHeader eyebrow="Costs · التكاليف" title="Store Costs · تكاليف المتجر" subtitle="A single source of truth for every cost that shapes your true profit." action={<button className="button primary" onClick={() => navigate("/cost-settings")}><Settings2 size={14} /> Complete cost setup</button>} /><div className="grid grid-4" style={{ marginBottom: 15 }}><StatCard label="Total costs this month" value="71,280 SAR" delta="+7.4% vs last month" icon={Database} down /><StatCard label="Configured costs" value="18" delta="82% coverage" icon={Check} /><StatCard label="Missing costs" value="3" delta="May affect accuracy" icon={CircleHelp} down /><StatCard label="Estimated costs" value="14,600 SAR" delta="Ads + overhead allocation" icon={Lightbulb} /></div><div className="grid grid-main"><div className="panel panel-accent panel-pad"><div className="section-head"><div><h2>Cost overview</h2><p>Revenue 125,400 SAR → True costs 71,280 SAR → Net profit 54,120 SAR.</p></div><span className="tag amber">Incomplete data</span></div>{[["Product costs", "20,200 SAR", "Manual", "/cost-settings"], ["Shipping", "12,860 SAR", "Imported", "/shipping-costs"], ["Advertising", "18,000 SAR", "Manual + Estimated", "/advertising-costs"], ["Payment fees", "6,210 SAR", "Calculated", "/payment-fees"], ["Packaging", "3,840 SAR", "Manual", "/packaging-costs"], ["Subscriptions", "1,800 SAR", "Calculated", "/subscriptions"], ["Other costs", "8,370 SAR", "Not configured", "/other-costs"]].map(([label, value, source, href]) => <button className="metric-row" key={label} style={{ width: "100%", background: "none", color: "inherit", textAlign: "left" }} onClick={() => navigate(href)}><span>{label}</span><div style={{ display: "flex", alignItems: "center", gap: 10 }}><strong>{value}</strong><SourceBadge source={source} /><ChevronRight size={13} color="#7786a4" /></div></button>)}</div><div className="panel panel-pad"><div className="section-head"><div><h2>Cost quality</h2><p>Trust indicators for your profit number.</p></div><ShieldCheck size={17} color="#5bd3bb" /></div><div className="health-bars">{[["Configured",82],["Imported",46],["Calculated",71],["Estimated",38]].map(([label,value]) => <div className="health-line" key={label as string}><span>{label}</span><div className="bar-track"><div className="bar-fill" style={{ width: `${value}%` }} /></div><b>{value}%</b></div>)}</div><div className="panel soft panel-pad" style={{ marginTop: 18, borderColor: "rgba(232,164,68,.32)" }}><strong style={{ fontSize: 12 }}>بعض تكاليف متجرك غير مكتملة</strong><p style={{ color: "#8795b3", fontSize: 11, lineHeight: 1.5, margin: "6px 0 13px" }}>لذلك قد لا يكون صافي الربح دقيقًا. أكمل إعداد التكاليف لرفع دقة القرارات.</p><button className="button primary" onClick={() => navigate("/cost-settings")}><Settings2 size={13} /> إكمال إعداد التكاليف</button></div></div></div><CostSemanticPanel rules={costConfigurationModels} title="Cost configuration status" /><div className="panel panel-pad" style={{ marginTop: 15 }}><div className="section-head"><div><h2>Cost edit history</h2><p>Changes are logged for trust and future Business Brain learning.</p></div><Clock3 size={16} color="#8290af" /></div><div className="metric-row"><span>Shipping Cost · 18 Sep 2026</span><strong>18 SAR → 20 SAR · Ayman</strong></div><div className="metric-row"><span>Pima Purchase Cost · 16 Sep 2026</span><strong>40 SAR → 42 SAR · Ayman</strong></div></div></>; }

function ManagementTable({ type }: { type: "shipping" | "payment" | "packaging" | "advertising" | "other" }) { const config = { shipping: { title: "Shipping Costs · تكاليف الشحن", eyebrow: "Costs · Shipping", subtitle: "Configure shipping companies, zones, and a reliable fallback value.", headers: ["Company", "Cost / shipment", "Zone", "Source", "Status"], rows: [["SPL", "18 SAR", "All zones", "Imported", "Active"], ["Aramex", "22 SAR", "All zones", "Manual", "Active"], ["SMSA", "20 SAR", "Riyadh / Jeddah", "Manual", "Active"]] }, payment: { title: "Payment Fees · رسوم الدفع", eyebrow: "Costs · Payment", subtitle: "Actual transaction fees override these provider rules when available.", headers: ["Payment method", "% fee", "Fixed fee", "Source", "Status"], rows: [["Mada", "2.5%", "0 SAR", "Calculated", "Active"], ["Visa / Mastercard", "2.9%", "1 SAR", "Calculated", "Active"], ["Tamara", "Configured", "—", "Manual", "Active"], ["Tabby", "Configured", "—", "Manual", "Inactive"]] }, packaging: { title: "Packaging Costs · تكلفة التغليف", eyebrow: "Costs · Packaging", subtitle: "Apply packaging costs per order or per product automatically.", headers: ["Packaging", "Cost", "Cost type", "Source", "Status"], rows: [["Standard Box", "3 SAR", "Per order", "Manual", "Active"], ["Premium Box", "7 SAR", "Per order", "Manual", "Active"], ["Gift wrap", "4 SAR", "Per product", "Manual", "Inactive"]] }, advertising: { title: "Advertising Costs · تكاليف الإعلانات", eyebrow: "Costs · Advertising", subtitle: "Track channel spend and label allocation as imported, manual, or estimated.", headers: ["Channel", "This month spend", "Allocation", "Source", "Status"], rows: [["Meta Ads", "10,000 SAR", "12 SAR / order", "Manual", "Active"], ["TikTok Ads", "5,000 SAR", "8 SAR / order", "Manual", "Active"], ["Snapchat Ads", "3,000 SAR", "Not allocated", "Imported", "Active"], ["Google Ads", "Not configured", "Not configured", "Not configured", "Inactive"]] }, other: { title: "Other Costs · تكاليف أخرى", eyebrow: "Costs · Other", subtitle: "Create custom business costs using a frequency and calculation type that fits.", headers: ["Cost name", "Amount", "Frequency", "Calculation", "Status"], rows: [["Warehouse Rent", "5,000 SAR", "Monthly", "Fixed", "Active"], ["Employee", "4,500 SAR", "Monthly", "Fixed", "Active"], ["Software", "200 SAR", "Monthly", "Per order", "Active"], ["Bank Fees", "Not configured", "Custom", "Percentage", "Inactive"]] } }[type]; const semanticRules = costConfigurationModels.filter((rule) => rule.category === ({ shipping: "shipping", payment: "payment_fee", packaging: "packaging", advertising: "advertising", other: "other" } as const)[type]); const [rows, setRows] = useState(config.rows); return <><PageHeader eyebrow={config.eyebrow} title={config.title} subtitle={config.subtitle} action={<button className="button primary" onClick={() => { setRows((r) => [...r, ["New cost rule", "0 SAR", "Custom", "Manual", "Draft"]]); toast("New cost rule added. Edit the values to save it."); }}><Plus size={14} /> Add {type === "payment" ? "payment method" : "cost"}</button>} /><div className="panel panel-pad"><div className="section-head"><div><h2>Active cost rules</h2><p>Rules apply automatically to future True Cost calculations.</p></div><div className="filter-row"><button className="filter-chip active">All</button><button className="filter-chip">Active</button><button className="filter-chip">Inactive</button></div></div><CostSemanticPanel rules={semanticRules} title="Rule semantics" /><div className="table-wrap"><table><thead><tr>{config.headers.map((h) => <th key={h}>{h}</th>)}<th>Actions</th></tr></thead><tbody>{rows.map((row, i) => <tr key={`${row[0]}-${i}`}>{row.map((cell, j) => <td key={`${row[0]}-${j}`}>{j === row.length - 2 ? <SourceBadge source={cell} /> : j === row.length - 1 ? <span className={`tag ${cell === "Active" ? "teal" : "amber"}`}>{cell}</span> : <strong>{cell}</strong>}</td>)}<td><div style={{ display: "flex", gap: 6 }}><button className="button ghost" onClick={() => toast(`${row[0]} editor opened. Changes will recalculate True Cost.`)}>Edit</button><button className="button ghost" onClick={() => toast(`${row[0]} disabled for future calculations.`)}>{row[row.length - 1] === "Active" ? "Disable" : "Enable"}</button></div></td></tr>)}</tbody></table></div></div><div className="grid grid-2" style={{ marginTop: 15 }}><div className="panel panel-pad"><div className="section-head"><div><h2>Automatic application</h2><p>Configured once, applied to future sales.</p></div><Zap size={17} color="#9c90f5" /></div><div className="metric-row"><span>Default rule</span><strong>Apply to every eligible order</strong></div><div className="metric-row"><span>Missing values</span><strong className="warn">Show warning · never assume zero</strong></div><div className="metric-row"><span>Source priority</span><strong>Imported → Calculated → Manual</strong></div></div><div className="panel panel-pad"><div className="section-head"><div><h2>Last update</h2><p>Cost changes remain auditable.</p></div><Clock3 size={16} color="#8290af" /></div><div className="metric-row"><span>Last updated</span><strong>18 Sep 2026</strong></div><div className="metric-row"><span>Changed by</span><strong>Ayman Al-Mutairi</strong></div><div className="metric-row"><span>Impact</span><strong className="good">True Profit recalculated</strong></div></div></div></>; }

function CostSettings() { const [saved, setSaved] = useState(false); const rows = [["IRONCLAD Pima T-Shirt", "42 SAR / unit", "Manual"], ["IRONCLAD Spandex T-Shirt", "31 SAR / unit", "Manual"], ["Supplier shipping", "3 SAR / unit", "Manual"], ["Customs / import", "Not configured", "Add cost"]]; return <><PageHeader eyebrow="Costs · Product Costs" title="Product Costs · تكلفة المنتجات" subtitle="Edit purchase, supplier shipping, import, and other per-unit costs. True product cost recalculates automatically." action={<button className={`button ${saved ? "success" : "primary"}`} onClick={() => { setSaved(true); toast("Product cost rules saved and True Product Cost recalculated."); }}>{saved ? <><Check size={14} /> Saved</> : <><Check size={14} /> Save product costs</>}</button>} /><div className="panel panel-accent panel-pad"><div className="section-head"><div><h2>Product cost management</h2><p>Product · Variant · Selling price · Purchase cost · Supplier shipping · Import cost · True product cost</p></div><button className="button ghost" onClick={() => toast("Product variant editor opened.")}><Plus size={13} /> Add product cost</button></div><CostSemanticPanel rules={costConfigurationModels.filter((rule) => rule.category === "product_cost" || rule.category === "customs")} title="Product cost configuration" /><div className="table-wrap"><table><thead><tr><th>Product</th><th>Variant</th><th>Selling price</th><th>Purchase</th><th>Supplier shipping</th><th>Import</th><th>True product cost</th><th>Last updated</th><th></th></tr></thead><tbody>{[["IRONCLAD Pima T-Shirt","Black / M","149 SAR","42 SAR","3 SAR","0 SAR","45 SAR"],["IRONCLAD Spandex T-Shirt","Black / M","129 SAR","31 SAR","3 SAR","0 SAR","34 SAR"]].map((r) => <tr key={r[0]}>{r.map((cell, i) => <td key={i}>{i === 0 ? <strong className="product-name">{cell}</strong> : <strong>{cell}</strong>}</td>)}<td>18 Sep 2026</td><td><button className="button ghost" onClick={() => toast(`${r[0]} editor opened. Purchase, shipping, import, and other costs can be changed.`)}>تعديل</button></td></tr>)}</tbody></table></div></div><div className="panel panel-pad" style={{ marginTop: 15 }}><div className="section-head"><div><h2>Product Cost Editor</h2><p>IRONCLAD Pima T-Shirt · Black / M · demo form</p></div><span className="tag violet">Per unit</span></div><div className="grid grid-4"><div className="panel soft panel-pad"><div className="stat-label">Purchase Cost</div><div className="stat-value" style={{ fontSize: 20 }}>42 SAR</div></div><div className="panel soft panel-pad"><div className="stat-label">Supplier Shipping</div><div className="stat-value" style={{ fontSize: 20 }}>3 SAR</div></div><div className="panel soft panel-pad"><div className="stat-label">Customs / Import</div><div className="stat-value" style={{ fontSize: 20 }}>0 SAR</div></div><div className="panel soft panel-pad"><div className="stat-label">Other Product Cost</div><div className="stat-value" style={{ fontSize: 20 }}>0 SAR</div></div></div><div className="metric-row" style={{ marginTop: 15 }}><span>Calculation type</span><div className="filter-row"><button className="filter-chip active">Per unit</button><button className="filter-chip">Percentage</button><button className="filter-chip">Fixed amount</button></div></div><div className="panel soft panel-pad" style={{ marginTop: 15 }}><div className="metric-row"><span>True Product Cost</span><strong className="good">45 SAR</strong></div><div className="metric-row"><span>Update effect</span><strong>True Profit and Net Margin recalculate</strong></div></div></div></>; }

